package io.github.diodeme.ji.storage.sqlite;

import java.util.List;

/** One immutable forward-only SQLite schema transition. */
public record SqliteMigration(int version, String name, List<String> statements) {
    public SqliteMigration {
        if (version < 1 || name == null || name.isBlank() || statements == null || statements.isEmpty()
                || statements.stream().anyMatch(value -> value == null || value.isBlank())) {
            throw new IllegalArgumentException("invalid SQLite migration");
        }
        statements = List.copyOf(statements);
    }
}
